-- =========================================================================
-- Auto-create a profile row when a new auth user signs up.
-- =========================================================================
create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  insert into public.profiles (id, full_name, units)
  values (new.id, new.raw_user_meta_data->>'full_name', 'metric')
  on conflict (id) do nothing;
  return new;
end;
$$;

create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function public.handle_new_user();

-- ── from 20260731120000_add_weekly_routine.sql ──────────────────────────────────
-- Adds a per-user weekly training split, e.g. { "monday": "CHEST", "tuesday": "BACK" }.
-- Missing/null day keys mean rest day. Values are the same category strings used
-- by public.workouts.category (CHEST/BACK/LEGS/SHOULDERS/ARMS/ABS).

alter table public.profiles
  add column weekly_routine jsonb not null default '{}'::jsonb;

-- ── from 20260804000000_atomic_xp_increment.sql ──────────────────────────────────
-- awardXP() previously read profiles.total_xp into JS, added the award, then
-- wrote the sum back (see src/lib/xp.ts). Two near-simultaneous awards (e.g.
-- logging water and a meal back to back, since the tabs layout keeps all log
-- modals mounted at once) could both read the same starting value and one
-- write would silently clobber the other, losing XP.
--
-- This makes the increment atomic at the database layer. auth.uid() is used
-- instead of a passed-in user id so the function can only ever touch the
-- caller's own row, regardless of what the client sends.
create or replace function public.increment_xp(p_xp integer)
returns integer
language plpgsql
security invoker
set search_path = public
as $$
declare
  new_xp integer;
begin
  update public.profiles
  set total_xp = coalesce(total_xp, 0) + p_xp
  where id = auth.uid()
  returning total_xp into new_xp;

  return new_xp;
end;
$$;

grant execute on function public.increment_xp(integer) to authenticated;

-- ── from 20260804010000_workout_photos.sql ──────────────────────────────────
-- Lets a user attach one photo per workout session. The calendar shows the
-- most recently-logged photo for a day as a corner thumbnail (computed
-- client-side from the workouts already loaded for the month — no new
-- column needed for that "latest wins" rule).
--
-- Photos are stored in a private bucket, one object per workout at
-- "{user_id}/{workout_id}.jpg", and served to the app via short-lived
-- signed URLs rather than public URLs.

alter table public.workouts
  add column photo_path text;

insert into storage.buckets (id, name, public)
values ('workout-photos', 'workout-photos', false)
on conflict (id) do nothing;

create policy "Users can upload their own workout photos"
  on storage.objects for insert
  to authenticated
  with check (
    bucket_id = 'workout-photos'
    and (storage.foldername(name))[1] = auth.uid()::text
  );

create policy "Users can view their own workout photos"
  on storage.objects for select
  to authenticated
  using (
    bucket_id = 'workout-photos'
    and (storage.foldername(name))[1] = auth.uid()::text
  );

create policy "Users can replace their own workout photos"
  on storage.objects for update
  to authenticated
  using (
    bucket_id = 'workout-photos'
    and (storage.foldername(name))[1] = auth.uid()::text
  )
  with check (
    bucket_id = 'workout-photos'
    and (storage.foldername(name))[1] = auth.uid()::text
  );

create policy "Users can delete their own workout photos"
  on storage.objects for delete
  to authenticated
  using (
    bucket_id = 'workout-photos'
    and (storage.foldername(name))[1] = auth.uid()::text
  );

-- ── from 20260805000000_leaderboards.sql ──────────────────────────────────
-- Leaderboards: global rankings by level (total_xp) and by log frequency for
-- strength (workouts) and cardio (cardio_logs) — counts of *sessions logged*,
-- not weight lifted or pace, so there's nothing for a user to self-report
-- that inflates their rank beyond "I showed up and logged it".
--
-- Every table involved (profiles, workouts, cardio_logs) has RLS locked to
-- `auth.uid() = user_id` (see baseline_schema.sql), so a user cannot
-- normally SELECT another user's row at all. Rather than loosening that RLS
-- — which would let any user read every other user's weight_kg, age, goal,
-- notes, etc. — these are narrow SECURITY DEFINER functions: they run with
-- elevated privilege internally, but the RETURNS TABLE signature is the
-- only thing ever exposed to callers (a name and an aggregate number,
-- nothing else). limit_count is capped at 200 server-side regardless of
-- what a client passes in.

-- =========================================================================
-- Top N by level (profiles.total_xp)
-- =========================================================================
create or replace function public.get_level_leaderboard(limit_count integer default 50)
returns table (user_id uuid, full_name text, total_xp integer, level integer, rnk bigint)
language sql
security definer
set search_path = public
stable
as $$
  select
    p.id as user_id,
    p.full_name,
    coalesce(p.total_xp, 0) as total_xp,
    floor(sqrt(greatest(coalesce(p.total_xp, 0), 0) / 100.0))::integer as level,
    rank() over (order by coalesce(p.total_xp, 0) desc) as rnk
  from public.profiles p
  order by total_xp desc
  limit least(coalesce(limit_count, 50), 200);
$$;

revoke all on function public.get_level_leaderboard(integer) from public;
grant execute on function public.get_level_leaderboard(integer) to authenticated;

-- Caller's own level rank, even when outside the top N returned above.
create or replace function public.get_my_level_rank()
returns table (rnk bigint, total_xp integer, level integer)
language sql
security definer
set search_path = public
stable
as $$
  select ranked.rnk, ranked.total_xp, ranked.level
  from (
    select
      p.id,
      coalesce(p.total_xp, 0) as total_xp,
      floor(sqrt(greatest(coalesce(p.total_xp, 0), 0) / 100.0))::integer as level,
      rank() over (order by coalesce(p.total_xp, 0) desc) as rnk
    from public.profiles p
  ) ranked
  where ranked.id = auth.uid();
$$;

revoke all on function public.get_my_level_rank() from public;
grant execute on function public.get_my_level_rank() to authenticated;

-- =========================================================================
-- Top N by strength sessions logged (row count in public.workouts per user)
-- =========================================================================
create or replace function public.get_strength_leaderboard(limit_count integer default 50)
returns table (user_id uuid, full_name text, log_count bigint, rnk bigint)
language sql
security definer
set search_path = public
stable
as $$
  select
    w.user_id,
    p.full_name,
    count(*) as log_count,
    rank() over (order by count(*) desc) as rnk
  from public.workouts w
  join public.profiles p on p.id = w.user_id
  group by w.user_id, p.full_name
  order by log_count desc
  limit least(coalesce(limit_count, 50), 200);
$$;

revoke all on function public.get_strength_leaderboard(integer) from public;
grant execute on function public.get_strength_leaderboard(integer) to authenticated;

-- Caller's own strength rank — LEFT JOIN so a user with zero workouts still
-- gets a (last-place) rank back instead of no row at all.
create or replace function public.get_my_strength_rank()
returns table (rnk bigint, log_count bigint)
language sql
security definer
set search_path = public
stable
as $$
  select ranked.rnk, ranked.log_count
  from (
    select
      p.id,
      count(w.id) as log_count,
      rank() over (order by count(w.id) desc) as rnk
    from public.profiles p
    left join public.workouts w on w.user_id = p.id
    group by p.id
  ) ranked
  where ranked.id = auth.uid();
$$;

revoke all on function public.get_my_strength_rank() from public;
grant execute on function public.get_my_strength_rank() to authenticated;

-- =========================================================================
-- Top N by cardio sessions logged (row count in public.cardio_logs per user)
-- =========================================================================
create or replace function public.get_cardio_leaderboard(limit_count integer default 50)
returns table (user_id uuid, full_name text, log_count bigint, rnk bigint)
language sql
security definer
set search_path = public
stable
as $$
  select
    c.user_id,
    p.full_name,
    count(*) as log_count,
    rank() over (order by count(*) desc) as rnk
  from public.cardio_logs c
  join public.profiles p on p.id = c.user_id
  group by c.user_id, p.full_name
  order by log_count desc
  limit least(coalesce(limit_count, 50), 200);
$$;

revoke all on function public.get_cardio_leaderboard(integer) from public;
grant execute on function public.get_cardio_leaderboard(integer) to authenticated;

-- Caller's own cardio rank — same LEFT JOIN reasoning as strength above.
create or replace function public.get_my_cardio_rank()
returns table (rnk bigint, log_count bigint)
language sql
security definer
set search_path = public
stable
as $$
  select ranked.rnk, ranked.log_count
  from (
    select
      p.id,
      count(c.id) as log_count,
      rank() over (order by count(c.id) desc) as rnk
    from public.profiles p
    left join public.cardio_logs c on c.user_id = p.id
    group by p.id
  ) ranked
  where ranked.id = auth.uid();
$$;

revoke all on function public.get_my_cardio_rank() from public;
grant execute on function public.get_my_cardio_rank() to authenticated;

-- ── from 20260806000000_nutrition_goals.sql ──────────────────────────────────
-- Adds the fields needed to calculate a personalized calorie + macro target
-- (Mifflin-St Jeor BMR -> TDEE -> goal-adjusted calories -> macro split, see
-- src/lib/nutrition.ts). All three are optional/have safe defaults —
-- computeNutritionTargets() falls back to a sex-neutral BMR formula, a
-- 'maintain' goal, and a 'moderate' pace whenever they're unset, so no
-- backfill is required for existing rows.
--
-- `activity_level` already exists as a free-text column (see
-- 20260727000000_baseline_schema.sql) holding user-typed values like
-- "Moderate" or "Very active" from the old Edit Profile text input. It is
-- NOT constrained here on purpose — doing so would break any existing row
-- that doesn't match the new canonical slugs ('sedentary' | 'light' |
-- 'moderate' | 'active' | 'very_active'). The app only ever writes those
-- slugs going forward (via the new Nutrition Goals settings screen);
-- computeNutritionTargets() falls back to the 'moderate' multiplier for
-- anything else it finds in that column.

-- IF NOT EXISTS on each column makes this safe to paste and run again if a
-- prior attempt partially applied (e.g. added `sex` then failed later) —
-- Postgres errors instantly on a plain ADD COLUMN if the column is already
-- there, this just skips whatever's already in place.
alter table public.profiles
  add column if not exists sex               text check (sex in ('male', 'female')),
  add column if not exists weight_goal_type  text not null default 'maintain' check (weight_goal_type in ('lose', 'maintain', 'gain')),
  add column if not exists goal_pace         text not null default 'moderate' check (goal_pace in ('mild', 'moderate', 'aggressive'));

-- ── from 20260810000000_custom_meals.sql ──────────────────────────────────
-- User-defined quick-add meals (Settings > Nutrition > Custom Meals). Each
-- row is just a name + calorie count the user enters once, then reuses as a
-- one-tap chip in the Log Meal sheet's quick add row instead of retyping the
-- same meal every time. Deliberately minimal (no macros/meal_type) to match
-- what the settings screen actually collects — see src/app/custom-meals.tsx.

create table public.custom_meals (
  id          uuid primary key default gen_random_uuid(),
  user_id     uuid not null references auth.users (id) on delete cascade,
  name        text not null,
  calories    integer not null,
  created_at  timestamptz default now()
);

alter table public.custom_meals enable row level security;

create policy "Users manage own custom meals"
  on public.custom_meals
  for all
  using (auth.uid() = user_id)
  with check (auth.uid() = user_id);

-- RLS policies alone aren't enough — Postgres still checks table-level
-- privileges before RLS is evaluated. The rest of this schema was
-- reconstructed from a live project (see baseline_schema.sql) whose default
-- privileges already covered every pre-existing table, so this grant was
-- never needed until now. Explicit here so a fresh project reproduces it.
grant select, insert, update, delete on public.custom_meals to authenticated;

-- ── from 20260810010000_grant_log_tables.sql ──────────────────────────────────
-- Defensive grant for the five original log tables (workouts, calorie_logs,
-- cardio_logs, water_logs, weight_logs). Insert/select already work today,
-- so those privileges clearly exist from whatever default-privilege setup
-- happened at project bootstrap (see baseline_schema.sql) — but that setup
-- predates version control, so it's unverified whether it ever covered
-- update/delete too. custom_meals (20260810000000_custom_meals.sql) showed
-- that this project's default privileges don't reliably extend to new
-- needs, so as we add edit/delete UI for every log type, grant explicitly
-- rather than assume. Safe to run even if these were already granted.
grant select, insert, update, delete on public.workouts     to authenticated;
grant select, insert, update, delete on public.calorie_logs to authenticated;
grant select, insert, update, delete on public.cardio_logs  to authenticated;
grant select, insert, update, delete on public.water_logs   to authenticated;
grant select, insert, update, delete on public.weight_logs  to authenticated;

-- ── from 20260812000000_delete_own_account.sql ──────────────────────────────────
-- Lets an authenticated user permanently delete their own account in-app
-- (Settings > Danger zone > Delete Account), replacing the previous
-- email-support-and-wait-48-hours flow. Required for App Store review
-- (Guideline 5.1.1(v): apps that support account creation must also offer
-- in-app account deletion, not just a request-by-email path).
--
-- Deleting the auth.users row cascades to every table that FKs it with
-- `on delete cascade` — profiles, workouts, calorie_logs, cardio_logs,
-- water_logs, weight_logs, custom_meals (see baseline_schema.sql and
-- 20260810000000_custom_meals.sql) — so no per-table cleanup is needed
-- here. Workout photos in Storage are NOT covered by this cascade (Storage
-- objects aren't linked to auth.users by a `references` FK), so the app
-- deletes those explicitly before calling this function — see
-- deleteAllWorkoutPhotos in src/utils/workoutPhotos.ts.
--
-- A plain client can't delete from auth.users directly (no table
-- privileges are ever granted there), so this is a SECURITY DEFINER
-- function: it runs with the privilege of whoever owns it (the
-- postgres/supabase_admin role, which does have access to auth.users), but
-- the `where id = auth.uid()` clause means a caller can only ever delete
-- their own row — there is no user_id parameter for them to pass anyone
-- else's id.
create or replace function public.delete_user()
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  delete from auth.users where id = auth.uid();
end;
$$;

revoke all on function public.delete_user() from public;
grant execute on function public.delete_user() to authenticated;

